  CW += c[36] * 57.072000;  // CH3CHCHO
  CW += c[37] * 74.079000;  // AC3H5OOH
  CW += c[38] * 40.065000;  // C3H4-P
  CW += c[39] * 40.065000;  // C3H4-A
  CW += c[40] * 39.057000;  // C3H3
  CW += c[41] * 38.049000;  // C3H2
  CW += c[42] * 56.064000;  // C2H3CHO
