  y[7] = c[7] * 34.014000 * CWinv;
  y[8] = c[8] * 33.006000 * CWinv;
  y[9] = c[9] * 28.010000 * CWinv;
  y[10] = c[10] * 44.009000 * CWinv;
  y[11] = c[11] * 16.043000 * CWinv;
  y[12] = c[12] * 15.035000 * CWinv;
  y[13] = c[13] * 14.027000 * CWinv;
  y[14] = c[14] * 30.026000 * CWinv;
  y[15] = c[15] * 29.018000 * CWinv;
  y[16] = c[16] * 30.026000 * CWinv;
  y[17] = c[17] * 30.070000 * CWinv;
  y[18] = c[18] * 29.062000 * CWinv;
  y[19] = c[19] * 62.068000 * CWinv;
  y[20] = c[20] * 61.060000 * CWinv;
  y[21] = c[21] * 28.054000 * CWinv;
  y[22] = c[22] * 27.046000 * CWinv;
  y[23] = c[23] * 58.036000 * CWinv;
  y[24] = c[24] * 59.044000 * CWinv;
  y[25] = c[25] * 42.037000 * CWinv;
  y[26] = c[26] * 26.038000 * CWinv;
  y[27] = c[27] * 45.061000 * CWinv;
  y[28] = c[28] * 77.059000 * CWinv;
  y[29] = c[29] * 43.045000 * CWinv;
  y[30] = c[30] * 42.037000 * CWinv;
  y[31] = c[31] * 41.029000 * CWinv;
  y[32] = c[32] * 44.097000 * CWinv;
  y[33] = c[33] * 43.089000 * CWinv;
  y[34] = c[34] * 42.081000 * CWinv;
  y[35] = c[35] * 41.073000 * CWinv;
  y[36] = c[36] * 57.072000 * CWinv;
  y[37] = c[37] * 74.079000 * CWinv;
  y[38] = c[38] * 40.065000 * CWinv;
  y[39] = c[39] * 40.065000 * CWinv;
