  qf[379] *= k_f;
  qr[379] *= k_f * exp(-(g_RT[2] - g_RT[35] + g_RT[39])) * (refC);
  // reaction 380:  C3H4-A + H <=> C2H2 + CH3
  k_f = 331 * exp((1.14) * logT - (8858.12296816048) * invT);
  qf[380] *= k_f;
  qr[380] *= k_f * exp(-(g_RT[2] - g_RT[12] - g_RT[26] + g_RT[39]));
  // reaction 381:  C3H4-P + H <=> C2H2 + CH3
  k_f = 172000000 * exp((-0.01) * logT - (6088.92165623711) * invT);
  qf[381] *= k_f;
  qr[381] *= k_f * exp(-(g_RT[2] - g_RT[12] - g_RT[26] + g_RT[38]));
  // reaction 382:  C3H4-P + H <=> C3H5-A
  k_f = 2.2e+53 * exp((-13.61) * logT - (18870.624967677) * invT);
  qf[382] *= k_f;
  qr[382] *= k_f * exp(-(g_RT[2] - g_RT[35] + g_RT[38])) * (refC);
  // reaction 383:  C2H2 + CH3 <=> C3H5-A
  k_f = 4.4e+43 * exp((-11.4) * logT - (18920.9466342575) * invT);
  qf[383] *= k_f;
  qr[383] *= k_f * exp(-(g_RT[12] + g_RT[26] - g_RT[35])) * (refC);
  // reaction 384:  C3H4-P + O <=> C3H3 + OH
  k_f = 1440000000 * exp((-0.82) * logT - (3859.6718267222) * invT);
  qf[384] *= k_f;
  qr[384] *= k_f * exp(-(g_RT[4] - g_RT[6] + g_RT[38] - g_RT[40]));
  // reaction 385:  C3H4-P + O <=> C2H3 + HCO
  k_f = 24000000 * exp((-0.219) * logT - (2143.70299632811) * invT);
