  qr[391] *= k_f * exp(-(-g_RT[2] + g_RT[4] + g_RT[38] - g_RT_qss[6]));
  // reaction 392:  C3H4-A + O <=> C3H3 + OH
  k_f = 524000 * exp((0.7) * logT - (2958.91399493175) * invT);
  qf[392] *= k_f;
  qr[392] *= k_f * exp(-(g_RT[4] - g_RT[6] + g_RT[39] - g_RT[40]));
  // reaction 393:  C3H4-A + O <=> C2H4 + CO
  k_f = 6.24 * exp((2.05) * logT - (90.5789998448495) * invT);
  qf[393] *= k_f;
  qr[393] *= k_f * exp(-(g_RT[4] - g_RT[9] - g_RT[21] + g_RT[39]));
  // reaction 394:  CH3CHCHO <=> C2H3CHO + H
  k_f = 5.82e+24 * exp((-3.71) * logT - (30555.3159476626) * invT);
  qf[394] *= k_f;
  qr[394] *= k_f * exp(-(-g_RT[2] + g_RT[36] - g_RT[42])) * (refCinv);
  // reaction 395:  C3H3 <=> C3H2 + H
  k_f = 4.43e+31 * exp((-4.59) * logT - (52586.1415765932) * invT);
  qf[395] *= k_f;
  qr[395] *= k_f * exp(-(-g_RT[2] + g_RT[40] - g_RT[41])) * (refCinv);
  // reaction 396:  C3H3 + HCO <=> C3H4-A + CO
  k_f = 25000000;
  qf[396] *= k_f;
  qr[396] *= k_f * exp(-(-g_RT[9] + g_RT[15] - g_RT[39] + g_RT[40]));
  // reaction 397:  C3H3 + HCO <=> C3H4-P + CO
  k_f = 25000000;
  qf[397] *= k_f;
  qr[397] *= k_f * exp(-(-g_RT[9] + g_RT[15] - g_RT[38] + g_RT[40]));
  // reaction 398:  C3H3 + O2 <=> CH2CO + HCO
  k_f = 0.17 * exp((1.7) * logT - (754.82499870708) * invT);
  qf[398] *= k_f;
  qr[398] *= k_f * exp(-(g_RT[3] - g_RT[15] - g_RT[30] + g_RT[40]));
  // reaction 399:  C3H3 + H <=> C3H2 + H2
  k_f = 0.214 * exp((2.52) * logT - (3750.47381024258) * invT);
  qf[399] *= k_f;
  qr[399] *= k_f * exp(-(-g_RT[1] + g_RT[2] + g_RT[40] - g_RT[41]));
  // reaction 400:  C3H3 + OH <=> C2H3 + HCO
  k_f = 2.29e+30 * exp((-6.25) * logT - (12127.5216458937) * invT);
  qf[400] *= k_f;
  qr[400] *= k_f * exp(-(g_RT[6] - g_RT[15] - g_RT[22] + g_RT[40]));
  // reaction 401:  C3H3 + OH <=> C2H2 + CO + H2
  k_f = 5490000000000 * exp((-1.8) * logT - (1387.36834762361) * invT);
  qf[401] *= k_f;
  qr[401] *= k_f * exp(-(-g_RT[1] + g_RT[6] - g_RT[9] - g_RT[26] + g_RT[40])) *
             (refCinv);
  // reaction 402:  C3H3 + OH <=> C2H4 + CO
  k_f = 1.77722e+29 * exp((-6.86) * logT - (3132.52374463438) * invT);
  qf[402] *= k_f;
  qr[402] *= k_f * exp(-(g_RT[6] - g_RT[9] - g_RT[21] + g_RT[40]));
  // reaction 403:  2 C3H3 => C6H6
  k_f = 3.89e+44 * exp((-11) * logT - (10215.2983158358) * invT);
  qf[403] *= k_f;
  qr[403] *= k_f * exp(-(2.000000 * g_RT[40] - g_RT[52])) * (refC);
  // reaction 404:  C3H3 + C3H4-A <=> C6H6 + H
  k_f = 1400000 * exp(-(5027.33577805547) * invT);
  qf[404] *= k_f;
  qr[404] *= k_f * exp(-(-g_RT[2] + g_RT[39] + g_RT[40] - g_RT[52]));
  // reaction 405:  C3H2 + OH => C2H2 + HCO
  k_f = 50000000;
  qf[405] *= k_f;
  qr[405] *= k_f * exp(-(g_RT[6] - g_RT[15] - g_RT[26] + g_RT[41]));
  // reaction 406:  C3H2 + OH => C2H2 + CO + H
  k_f = 1.844e+17 * exp((-2.6) * logT - (7935.37456807437) * invT);
  qf[406] *= k_f;
  qr[406] *= k_f * exp(-(-g_RT[2] + g_RT[6] - g_RT[9] - g_RT[26] + g_RT[41])) *
             (refCinv);
  // reaction 407:  C3H2 + O2 <=> C2H2 + CO2
  k_f = 1.15 * exp((2.245) * logT - (184.982446349815) * invT);
  qf[407] *= k_f;
  qr[407] *= k_f * exp(-(g_RT[3] - g_RT[10] - g_RT[26] + g_RT[41]));
  // reaction 408:  C3H2 + O2 <=> CO + H + HCCO
  k_f = 0.25 * exp((2.245) * logT - (184.982446349815) * invT);
  qf[408] *= k_f;
  qr[408] *= k_f * exp(-(-g_RT[2] + g_RT[3] - g_RT[9] - g_RT[31] + g_RT[41])) *
             (refCinv);
  // reaction 409:  C2H3 + HCO <=> C2H3CHO
  k_f = 18100000;
  qf[409] *= k_f;
  qr[409] *= k_f * exp(-(g_RT[15] + g_RT[22] - g_RT[42])) * (refC);
  // reaction 410:  C2H3CHO + H <=> C2H3CO + H2
  k_f = 13400000 * exp(-(1660.61499715557) * invT);
  qf[410] *= k_f;
  qr[410] *= k_f * exp(-(-g_RT[1] + g_RT[2] + g_RT[42] - g_RT_qss[6]));
  // reaction 411:  C2H3CHO + O <=> C2H3CO + OH
  k_f = 5940000 * exp(-(940.008731723216) * invT);
  qf[411] *= k_f;
  qr[411] *= k_f * exp(-(g_RT[4] - g_RT[6] + g_RT[42] - g_RT_qss[6]));
  // reaction 412:  C2H3CHO + OH <=> C2H3CO + H2O
  k_f = 9.24 * exp((1.5) * logT - (-484.09443250414) * invT);
  qf[412] *= k_f;
  qr[412] *= k_f * exp(-(-g_RT[5] + g_RT[6] + g_RT[42] - g_RT_qss[6]));
  // reaction 413:  C2H3CHO + O2 <=> C2H3CO + HO2
  k_f = 10050000 * exp(-(20480.9182982521) * invT);
  qf[413] *= k_f;
  qr[413] *= k_f * exp(-(g_RT[3] - g_RT[8] + g_RT[42] - g_RT_qss[6]));
  // reaction 414:  C2H3CHO + HO2 <=> C2H3CO + H2O2
  k_f = 3010000 * exp(-(5998.34265639226) * invT);
  qf[414] *= k_f;
  qr[414] *= k_f * exp(-(-g_RT[7] + g_RT[8] + g_RT[42] - g_RT_qss[6]));
  // reaction 415:  C2H3CHO + CH3 <=> C2H3CO + CH4
  k_f = 2.608 * exp((1.78) * logT - (2974.5137115717) * invT);
  qf[415] *= k_f;
  qr[415] *= k_f * exp(-(-g_RT[11] + g_RT[12] + g_RT[42] - g_RT_qss[6]));
  // reaction 416:  C2H3 + C2H3CHO <=> C2H3CO + C2H4
  k_f = 1740000 * exp(-(4247.14865939183) * invT);
  qf[416] *= k_f;
  qr[416] *= k_f * exp(-(-g_RT[21] + g_RT[22] + g_RT[42] - g_RT_qss[6]));
  // reaction 417:  C2H3 + CO <=> C2H3CO
  k_f = 151000 * exp(-(2420.4721625207) * invT);
  qf[417] *= k_f;
  qr[417] *= k_f * exp(-(g_RT[9] + g_RT[22] - g_RT_qss[6])) * (refC);
